<script setup lang="ts">
import { computed, ref } from 'vue';import { onShow } from '@dcloudio/uni-app';import { api } from '../../api/http'
const items=ref<any[]>([]),active=ref('全部');const tabs=['全部','电梯通知','缴费通知','维保通知','小区公告'];const filtered=computed(()=>active.value==='全部'?items.value:items.value.filter(i=>i.category===active.value));onShow(async()=>{try{items.value=await api.notices()}catch{}})
</script>
<template><view class="notice-page"><scroll-view class="tabs" scroll-x><view v-for="tab in tabs" :key="tab" :class="{active:active===tab}" @click="active=tab">{{ tab }}</view></scroll-view><view class="page"><view v-for="item in filtered" :key="item.id" class="notice card"><view class="notice-head"><text>{{ item.category }}</text><b v-if="item.pinned">置顶</b></view><strong>{{ item.title }}</strong><text class="content">{{ item.content }}</text><view class="time">管理处　{{ item.publishedAt.replace('T',' ').slice(0,16) }} <text>已读</text></view></view><view v-if="!filtered.length" class="empty">暂无公告通知</view></view></view></template>
<style lang="scss" scoped>.notice-page{max-width:920rpx;margin:auto}.tabs{white-space:nowrap;background:#fff;border-bottom:1rpx solid #e7ecf2}.tabs view{display:inline-flex;height:84rpx;padding:0 28rpx;align-items:center;position:relative;color:#687386}.tabs .active{color:#1768ed;font-weight:800}.tabs .active:after{content:"";position:absolute;left:30%;right:30%;bottom:0;height:5rpx;background:#1768ed}.notice{padding:24rpx;margin-bottom:16rpx}.notice-head{display:flex;justify-content:space-between}.notice-head>text{font-size:20rpx;border:1rpx solid #82afff;color:#1768ed;border-radius:7rpx;padding:4rpx 8rpx}.notice-head b{color:#ed3b3b;font-size:21rpx}.notice>strong{display:block;font-size:28rpx;margin:15rpx 0}.content{font-size:23rpx;line-height:1.6;color:#58657a}.time{font-size:20rpx;color:#929bad;margin-top:17rpx}.time text{float:right;color:#17a663}</style>

